import type { SupabaseClient } from '@supabase/supabase-js'
import { createClient } from '@/lib/supabase/server'
import { isElevatedPropertyStaffRole } from '@/lib/dashboard/property-staff-roles'

export type UiRole = 'owner' | 'admin' | 'manager' | 'staff'
type DbRole = 'owner' | 'admin' | 'manager' | 'staff'

export type RoleCategoryAccess = {
  selectedModuleKey?: string
  moduleAccessControl?: Record<string, Record<string, boolean>>
}

const roleMap: Record<UiRole, DbRole> = {
  owner: 'owner',
  admin: 'admin',
  manager: 'manager',
  staff: 'staff',
}

export type StaffManagementTableRow = {
  id: string
  name: string
  email: string
  role: 'Owner' | 'Admin' | 'Manager' | 'Staff'
  categories: string[] | 'All Categories'
  status: 'Active' | 'Pending' | 'Inactive'
  lastLogin: string
}

function formatStaffTableRoleLabel(dbRole: string): StaffManagementTableRow['role'] {
  const r = dbRole.toLowerCase()
  if (r === 'owner') return 'Owner'
  if (r === 'admin' || r === 'property_admin') return 'Admin'
  if (r === 'manager') return 'Manager'
  return 'Staff'
}

function formatStaffTableStatus(raw: string): StaffManagementTableRow['status'] {
  const s = raw.toLowerCase()
  if (s === 'pending') return 'Pending'
  if (s === 'inactive') return 'Inactive'
  return 'Active'
}

function formatStaffTableLastLogin(iso: string | undefined): string {
  if (!iso) return 'Never'
  try {
    return new Date(iso).toLocaleString(undefined, {
      dateStyle: 'medium',
      timeStyle: 'short',
    })
  } catch {
    return 'Never'
  }
}

function formatStaffInviteRoleLabel(dbRole: string): string {
  const r = dbRole.toLowerCase()
  if (r === 'owner') return 'Owner'
  if (r === 'admin' || r === 'property_admin') return 'Admin'
  if (r === 'manager') return 'Manager'
  if (r === 'staff') return 'Staff'
  return dbRole ? dbRole.charAt(0).toUpperCase() + dbRole.slice(1) : '—'
}

export { isElevatedPropertyStaffRole } from '@/lib/dashboard/property-staff-roles'

export class StaffManagementQueries {
  constructor(private readonly supabase: SupabaseClient) {}

  static async create(): Promise<StaffManagementQueries> {
    const supabase = await createClient()
    return new StaffManagementQueries(supabase as unknown as SupabaseClient)
  }

  async verifyPropertyAccess(input: {
    propertyId: string
    userId: string
  }): Promise<{ hasAccess: boolean; isAdmin: boolean }> {
    const { data: property } = await this.supabase
      .from('properties')
      .select('company_id')
      .eq('id', input.propertyId)
      .single()

    if (!property) {
      return { hasAccess: false, isAdmin: false }
    }

    const { data: company } = await this.supabase
      .from('companies')
      .select('owner_id')
      .eq('id', property.company_id)
      .single()

    if (company?.owner_id === input.userId) {
      return { hasAccess: true, isAdmin: true }
    }

    const { data: staffRecord } = await this.supabase
      .from('property_staff')
      .select('role')
      .eq('property_id', input.propertyId)
      .eq('user_id', input.userId)
      .single()

    if (staffRecord) {
      const isAdmin = isElevatedPropertyStaffRole(staffRecord.role)
      return { hasAccess: true, isAdmin }
    }

    return { hasAccess: false, isAdmin: false }
  }

  async getPropertyRoleCategories(input: {
    propertyId: string
  }): Promise<{ categoriesByRole: Record<UiRole, { id: string; name: string; access: RoleCategoryAccess }[]> }> {
    const { data, error: selectError } = await this.supabase
      .from('property_role_categories')
      .select('id, role, name, access')
      .eq('property_id', input.propertyId)
      .in('role', ['owner', 'admin', 'manager', 'staff'])
      .order('name', { ascending: true })

    if (selectError) {
      console.error('[StaffManagementQueries] Failed to fetch role categories', {
        propertyId: input.propertyId,
        error: selectError,
      })
      throw selectError
    }

    const grouped: Record<UiRole, { id: string; name: string; access: RoleCategoryAccess }[]> = {
      owner: [],
      admin: [],
      manager: [],
      staff: [],
    }

    for (const row of data ?? []) {
      const role = row.role as UiRole
      if (role !== 'owner' && role !== 'admin' && role !== 'manager' && role !== 'staff') continue
      grouped[role].push({
        id: row.id,
        name: row.name,
        access: (row.access as RoleCategoryAccess) ?? {},
      })
    }

    return { categoriesByRole: grouped }
  }

  async savePropertyRolesCategories(input: {
    propertyId: string
    categoriesByRole: Record<UiRole, { name: string }[]>
  }): Promise<{ savedCount: number }> {
    const roles: DbRole[] = ['owner', 'admin', 'manager', 'staff']

    const { data: existing, error: existingError } = await this.supabase
      .from('property_role_categories')
      .select('id, role, name, access')
      .eq('property_id', input.propertyId)
      .in('role', roles)

    if (existingError) {
      console.error('[StaffManagementQueries] Failed to load existing categories', {
        propertyId: input.propertyId,
        error: existingError,
      })
      throw existingError
    }

    const existingAccessByKey = new Map(
      (existing ?? []).map((r) => [`${r.role}::${r.name}`, (r.access as RoleCategoryAccess) ?? {}]),
    )

    const desired = (Object.keys(input.categoriesByRole) as UiRole[]).flatMap(
      (uiRole) => {
        const role = roleMap[uiRole]
        return input.categoriesByRole[uiRole].map((c) => {
          const name = c.name.trim()
          return {
            property_id: input.propertyId,
            role,
            name,
            access: existingAccessByKey.get(`${role}::${name}`) ?? {},
          }
        })
      },
    )

    const desiredKey = new Set(desired.map((r) => `${r.role}::${r.name}`))
    const toDeleteIds = (existing ?? [])
      .filter((r) => !desiredKey.has(`${r.role}::${r.name}`))
      .map((r) => r.id)

    if (toDeleteIds.length > 0) {
      const { error: deleteError } = await this.supabase
        .from('property_role_categories')
        .delete()
        .eq('property_id', input.propertyId)
        .in('id', toDeleteIds)

      if (deleteError) {
        console.error('[StaffManagementQueries] Failed to delete categories', {
          propertyId: input.propertyId,
          toDeleteIds,
          error: deleteError,
        })
        throw deleteError
      }
    }

    const { error: upsertError } = await this.supabase
      .from('property_role_categories')
      .upsert(desired, { onConflict: 'property_id,role,name' })

    if (upsertError) {
      console.error('[StaffManagementQueries] Failed to upsert categories', {
        propertyId: input.propertyId,
        desiredCount: desired.length,
        error: upsertError,
      })
      throw upsertError
    }

    return { savedCount: desired.length }
  }

  async savePropertyRoleCategoryAccess(input: {
    propertyId: string
    categoryId: string
    role: UiRole
    access: RoleCategoryAccess
  }): Promise<void> {
    const { error: upErr } = await this.supabase
      .from('property_role_categories')
      .update({ access: input.access })
      .eq('id', input.categoryId)
      .eq('property_id', input.propertyId)
      .eq('role', roleMap[input.role])

    if (upErr) {
      console.error('[StaffManagementQueries] Failed to save role category access', {
        propertyId: input.propertyId,
        categoryId: input.categoryId,
        role: input.role,
        error: upErr,
      })
      throw upErr
    }
  }

  async listPropertyStaff(propertyId: string): Promise<{
    id: string
    user_id: string | null
    role: string
    status: string
    role_category_id: string[] | null
  }[]> {
    const { data, error: selectError } = await this.supabase
      .from('property_staff')
      .select('id, user_id, role, status, role_category_id')
      .eq('property_id', propertyId)
      .order('created_at', { ascending: true })

    if (selectError) {
      console.error('[StaffManagementQueries] Failed to list property staff', {
        propertyId,
        error: selectError,
      })
      throw selectError
    }

    return data ?? []
  }

  async getStaffInviteStaffContextByUserId(userId: string): Promise<{
    roleLabel: string
    categoryNames: string[]
  }> {
    const { data: staffRows, error: staffError } = await this.supabase
      .from('property_staff')
      .select('role, role_category_id, property_id, status, created_at')
      .eq('user_id', userId)
      .order('created_at', { ascending: false })
      .limit(10)

    if (staffError) {
      console.error('[StaffManagementQueries] Failed to load staff for invite', {
        userId,
        error: staffError,
      })
      throw staffError
    }

    const staffRow =
      staffRows?.find((r) => r.status === 'pending') ?? staffRows?.[0] ?? null

    if (!staffRow?.property_id) {
      return { roleLabel: '—', categoryNames: [] }
    }

    const roleLabel = formatStaffInviteRoleLabel(staffRow.role ?? '')
    const ids: string[] = staffRow.role_category_id ?? []
    if (ids.length === 0) {
      return { roleLabel, categoryNames: [] }
    }

    const { data: cats, error: catErr } = await this.supabase
      .from('property_role_categories')
      .select('id, name')
      .eq('property_id', staffRow.property_id)
      .in('id', ids)

    if (catErr) {
      console.error(
        '[StaffManagementQueries] Failed to load categories for staff invite',
        {
          propertyId: staffRow.property_id,
          userId,
          error: catErr,
        },
      )
      throw catErr
    }

    const byId = new Map(
      (cats ?? []).map((c: { id: string; name: string }) => [c.id, c.name]),
    )
    const categoryNames = ids
      .map((id: string) => byId.get(id))
      .filter((n: string | undefined): n is string => Boolean(n))

    return { roleLabel, categoryNames }
  }

  async activatePendingStaffForUser(userId: string): Promise<void> {
    const { error } = await this.supabase
      .from('property_staff')
      .update({ status: 'active' })
      .eq('user_id', userId)
      .eq('status', 'pending')

    if (error) {
      console.error('[StaffManagementQueries] Failed to activate pending staff for user', {
        userId,
        error,
      })
      throw error
    }
  }

  async listStaffForManagementTable(
    propertyId: string,
    adminClient: SupabaseClient,
  ): Promise<StaffManagementTableRow[]> {
    const rows = await this.listPropertyStaff(propertyId)

    const { data: catRows, error: catErr } = await this.supabase
      .from('property_role_categories')
      .select('id, name')
      .eq('property_id', propertyId)

    if (catErr) {
      console.error('[StaffManagementQueries] Failed to load category names for staff table', {
        propertyId,
        error: catErr,
      })
      throw catErr
    }

    const categoryNameById = new Map(
      (catRows ?? []).map((c) => [c.id, c.name] as const),
    )

    return Promise.all(
      rows.map(async (row) => {
        const userId = row.user_id
        let email = ''
        let displayName = '—'
        let lastSignIn: string | undefined

        if (userId) {
          const { data: authData, error: authErr } =
            await adminClient.auth.admin.getUserById(userId)
          if (!authErr && authData.user) {
            const u = authData.user
            email = u.email ?? ''
            const meta = u.user_metadata as Record<string, unknown> | undefined
            const fromFullOrName =
              typeof meta?.full_name === 'string'
                ? meta.full_name
                : typeof meta?.name === 'string'
                  ? meta.name
                  : ''
            const first =
              typeof meta?.first_name === 'string' ? meta.first_name.trim() : ''
            const last =
              typeof meta?.last_name === 'string' ? meta.last_name.trim() : ''
            const fromParts = [first, last].filter(Boolean).join(' ')
            const resolved = fromFullOrName.trim() || fromParts.trim()
            displayName = resolved || '—'
            lastSignIn = u.last_sign_in_at ?? undefined
          }
        }

        const ids = row.role_category_id ?? []
        const categories: string[] | 'All Categories' =
          ids.length === 0
            ? 'All Categories'
            : ids
                .map((id) => categoryNameById.get(id))
                .filter((n): n is string => Boolean(n))

        return {
          id: row.id,
          name: displayName,
          email: email || '—',
          role: formatStaffTableRoleLabel(row.role),
          categories,
          status: formatStaffTableStatus(row.status),
          lastLogin: formatStaffTableLastLogin(lastSignIn),
        }
      }),
    )
  }

  async findAuthUserIdByEmail(
    adminClient: SupabaseClient,
    email: string,
  ): Promise<string | null> {
    const normalized = email.toLowerCase()
    let page = 1
    const perPage = 200

    for (;;) {
      const { data, error: listError } = await adminClient.auth.admin.listUsers({
        page,
        perPage,
      })

      if (listError) {
        throw new Error(listError.message)
      }

      const match = data.users.find(
        (u) => (u.email ?? '').toLowerCase() === normalized,
      )
      if (match?.id) return match.id

      if (data.nextPage == null) break
      page = data.nextPage
    }

    return null
  }

  async inviteStaff(input: {
    propertyId: string
    userId: string
    role: UiRole
    roleCategoryIds: string[]
    status: 'pending' | 'active' | 'inactive'
  }): Promise<{ invitedCount: number }> {
    const { data: existingStaff } = await this.supabase
      .from('property_staff')
      .select('id')
      .eq('property_id', input.propertyId)
      .eq('user_id', input.userId)
      .single()

    if (existingStaff) {
      console.error('[StaffManagementQueries] Staff already exists', {
        propertyId: input.propertyId,
        userId: input.userId,
      })
      throw new Error('Staff already exists')
    }

    const { error: insertError } = await this.supabase
      .from('property_staff')
      .insert({
        property_id: input.propertyId,
        user_id: input.userId,
        role: roleMap[input.role],
        role_category_id: input.roleCategoryIds,
        status: input.status,
        permissions: [],
      })

    if (insertError) {
      console.error('[StaffManagementQueries] Failed to insert staff', {
        propertyId: input.propertyId,
        userId: input.userId,
        error: insertError,
      })
      throw insertError
    }

    return { invitedCount: 1 }
  }

  async updatePropertyStaffAssignment(input: {
    propertyId: string
    staffId: string
    role: 'admin' | 'manager' | 'staff'
    allCategories: boolean
    roleCategoryIds: string[]
  }): Promise<void> {
    const { data: row, error: fetchErr } = await this.supabase
      .from('property_staff')
      .select('id, role')
      .eq('id', input.staffId)
      .eq('property_id', input.propertyId)
      .maybeSingle()

    if (fetchErr) {
      console.error('[StaffManagementQueries] Failed to load staff row for update', {
        propertyId: input.propertyId,
        staffId: input.staffId,
        error: fetchErr,
      })
      throw fetchErr
    }

    if (!row) {
      throw new Error('Staff assignment not found')
    }

    const currentRole = (row.role ?? '').toLowerCase()
    if (currentRole === 'owner') {
      throw new Error('Cannot change property owner from staff management')
    }

    const nextCategoryIds = input.allCategories ? [] : [...new Set(input.roleCategoryIds)]

    if (!input.allCategories) {
      if (nextCategoryIds.length === 0) {
        throw new Error('Select at least one category, or choose All Categories')
      }

      const { data: cats, error: catErr } = await this.supabase
        .from('property_role_categories')
        .select('id, role')
        .eq('property_id', input.propertyId)
        .in('id', nextCategoryIds)

      if (catErr) {
        console.error('[StaffManagementQueries] Failed to validate role categories', {
          propertyId: input.propertyId,
          error: catErr,
        })
        throw catErr
      }

      if (!cats || cats.length !== nextCategoryIds.length) {
        throw new Error('One or more category ids are invalid for this property')
      }

      for (const c of cats) {
        const cr = String(c.role ?? '').toLowerCase()
        const matchesAdmin = input.role === 'admin' && (cr === 'admin' || cr === 'property_admin')
        const matchesOther = input.role !== 'admin' && cr === input.role
        if (!matchesAdmin && !matchesOther) {
          throw new Error('Each selected category must belong to the chosen role')
        }
      }
    }

    const { error: upErr } = await this.supabase
      .from('property_staff')
      .update({
        role: input.role,
        role_category_id: nextCategoryIds,
      })
      .eq('id', input.staffId)
      .eq('property_id', input.propertyId)

    if (upErr) {
      console.error('[StaffManagementQueries] Failed to update property staff', {
        propertyId: input.propertyId,
        staffId: input.staffId,
        error: upErr,
      })
      throw upErr
    }
  }

  async deactivatePropertyStaffAssignment(input: {
    propertyId: string
    staffId: string
  }): Promise<void> {
    const { data: row, error: fetchErr } = await this.supabase
      .from('property_staff')
      .select('id, role, status')
      .eq('id', input.staffId)
      .eq('property_id', input.propertyId)
      .maybeSingle()

    if (fetchErr) {
      console.error('[StaffManagementQueries] Failed to load staff row for deactivate', {
        propertyId: input.propertyId,
        staffId: input.staffId,
        error: fetchErr,
      })
      throw fetchErr
    }

    if (!row) {
      throw new Error('Staff assignment not found')
    }

    const currentRole = (row.role ?? '').toLowerCase()
    if (currentRole === 'owner') {
      throw new Error('Cannot deactivate property owner from staff management')
    }

    const currentStatus = (row.status ?? '').toLowerCase()
    if (currentStatus === 'inactive') {
      throw new Error('Staff member is already inactive')
    }

    const { error: upErr } = await this.supabase
      .from('property_staff')
      .update({ status: 'inactive' })
      .eq('id', input.staffId)
      .eq('property_id', input.propertyId)

    if (upErr) {
      console.error('[StaffManagementQueries] Failed to deactivate property staff', {
        propertyId: input.propertyId,
        staffId: input.staffId,
        error: upErr,
      })
      throw upErr
    }
  }

  async reactivatePropertyStaffAssignment(input: {
    propertyId: string
    staffId: string
  }): Promise<void> {
    const { data: row, error: fetchErr } = await this.supabase
      .from('property_staff')
      .select('id, role, status')
      .eq('id', input.staffId)
      .eq('property_id', input.propertyId)
      .maybeSingle()

    if (fetchErr) {
      console.error('[StaffManagementQueries] Failed to load staff row for reactivate', {
        propertyId: input.propertyId,
        staffId: input.staffId,
        error: fetchErr,
      })
      throw fetchErr
    }

    if (!row) {
      throw new Error('Staff assignment not found')
    }

    const currentRole = (row.role ?? '').toLowerCase()
    if (currentRole === 'owner') {
      throw new Error('Cannot change property owner status from staff management')
    }

    const currentStatus = (row.status ?? '').toLowerCase()
    if (currentStatus !== 'inactive') {
      throw new Error('Only inactive staff members can be reactivated')
    }

    const { error: upErr } = await this.supabase
      .from('property_staff')
      .update({ status: 'active' })
      .eq('id', input.staffId)
      .eq('property_id', input.propertyId)

    if (upErr) {
      console.error('[StaffManagementQueries] Failed to reactivate property staff', {
        propertyId: input.propertyId,
        staffId: input.staffId,
        error: upErr,
      })
      throw upErr
    }
  }
}

import { type NextRequest } from 'next/server'
import type { SupabaseClient } from '@supabase/supabase-js'
import { z } from 'zod'
import { createSupabaseClientForApiRoute } from '@/lib/supabase/api-route-client'
import { success, error } from '@/lib/api/response'
import { ErrorCodes } from '@/lib/api/errors'
import { StaffManagementQueries } from '@/lib/dashboard/staff-management-queries'
import { resolveDashboardAccess, canManageStaffRoster } from '@/lib/rbac/dashboard-guards'

const StaffStatusBodySchema = z.object({
  status: z.enum(['inactive', 'active']),
})

const UpdateAccessBodySchema = z
  .object({
    role: z.enum(['admin', 'manager', 'staff']),
    allCategories: z.boolean(),
    roleCategoryIds: z.array(z.string().uuid()).default([]),
  })
  .superRefine((data, ctx) => {
    if (data.allCategories) return
    if (data.roleCategoryIds.length === 0) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: 'Select at least one category, or set allCategories to true',
        path: ['roleCategoryIds'],
      })
    }
  })

const PatchBodySchema = z.union([StaffStatusBodySchema, UpdateAccessBodySchema])

export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ propertyId: string; staffId: string }> },
) {
  try {
    const { propertyId, staffId } = await params
    const { supabase, user, error: authError } = await createSupabaseClientForApiRoute(request)

    if (authError || !user) {
      return error(ErrorCodes.AUTH_001, request)
    }

    const parsed = PatchBodySchema.safeParse(await request.json())
    if (!parsed.success) {
      const msg =
        parsed.error.errors.map((e) => e.message).join('; ') ||
        ErrorCodes.VALIDATION_ERROR.message
      return error(ErrorCodes.VALIDATION_ERROR.code, msg, ErrorCodes.VALIDATION_ERROR.status, request, {
        errors: parsed.error.errors,
      })
    }

    const access = await resolveDashboardAccess(supabase as never, propertyId, user.id)
    if (!access) {
      return error(
        ErrorCodes.AUTH_002.code,
        'No access to this property. Confirm the property ID and your assignment or company ownership.',
        ErrorCodes.AUTH_002.status,
        request,
      )
    }

    if (!canManageStaffRoster(access)) {
      return error(
        ErrorCodes.AUTH_002.code,
        'Updating staff requires an admin-level property role (owner, admin, or property_admin).',
        ErrorCodes.AUTH_002.status,
        request,
      )
    }

    const q = new StaffManagementQueries(supabase as unknown as SupabaseClient)

    if ('status' in parsed.data) {
      if (parsed.data.status === 'inactive') {
        await q.deactivatePropertyStaffAssignment({ propertyId, staffId })
        return success({ deactivated: true }, request)
      }
      await q.reactivatePropertyStaffAssignment({ propertyId, staffId })
      return success({ reactivated: true }, request)
    }

    await q.updatePropertyStaffAssignment({
      propertyId,
      staffId,
      role: parsed.data.role,
      allCategories: parsed.data.allCategories,
      roleCategoryIds: parsed.data.roleCategoryIds,
    })

    return success({ updated: true }, request)
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Unknown error'
    if (message === 'Staff assignment not found') {
      return error(
        ErrorCodes.RESOURCE_NOT_FOUND.code,
        message,
        ErrorCodes.RESOURCE_NOT_FOUND.status,
        request,
      )
    }
    if (
      message === 'Cannot change property owner from staff management' ||
      message === 'Cannot deactivate property owner from staff management' ||
      message === 'Cannot change property owner status from staff management'
    ) {
      return error(ErrorCodes.AUTH_002.code, message, ErrorCodes.AUTH_002.status, request)
    }
    if (message === 'Staff member is already inactive') {
      return error(
        ErrorCodes.VALIDATION_ERROR.code,
        message,
        ErrorCodes.VALIDATION_ERROR.status,
        request,
      )
    }
    if (message === 'Only inactive staff members can be reactivated') {
      return error(
        ErrorCodes.VALIDATION_ERROR.code,
        message,
        ErrorCodes.VALIDATION_ERROR.status,
        request,
      )
    }
    if (
      message.startsWith('One or more category') ||
      message.startsWith('Select at least one category') ||
      message.startsWith('Each selected category')
    ) {
      return error(
        ErrorCodes.VALIDATION_ERROR.code,
        message,
        ErrorCodes.VALIDATION_ERROR.status,
        request,
      )
    }
    return error(
      ErrorCodes.INTERNAL_ERROR.code,
      message,
      ErrorCodes.INTERNAL_ERROR.status,
      request,
    )
  }
}

'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { AlertTriangle } from 'lucide-react'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { useToast } from '@/hooks/use-toast'
import { isAccessDeniedError } from '@/lib/utils/is-access-denied-error'

export type DeactivateStaffDialogTarget = {
  id: string
  name: string
  status: 'Active' | 'Pending' | 'Inactive'
}

type DeactivateStaffDialogProps = {
  open: boolean
  onOpenChange: (open: boolean) => void
  propertyId: string
  staff: DeactivateStaffDialogTarget | null
  onDeactivated?: () => void
}

export function DeactivateStaffDialog({
  open,
  onOpenChange,
  propertyId,
  staff,
  onDeactivated,
}: DeactivateStaffDialogProps) {
  const router = useRouter()
  const { toast } = useToast()
  const [isSubmitting, setIsSubmitting] = useState(false)

  const handleConfirm = async () => {
    if (!staff || isSubmitting) return

    try {
      setIsSubmitting(true)
      const res = await fetch(
        `/api/v1/properties/${propertyId}/staff-management/staff/${staff.id}`,
        {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ status: 'inactive' }),
        },
      )
      const json: { success?: boolean; error?: { message?: string } } = await res.json().catch(() => ({}))
      if (!res.ok || json.success !== true) {
        throw new Error(json.error?.message ?? 'Failed to deactivate staff member')
      }
      toast({ title: 'Staff member deactivated' })
      onOpenChange(false)
      onDeactivated?.()
      router.refresh()
    } catch (err: unknown) {
      if (isAccessDeniedError(err)) {
        toast({
          title: 'Access denied',
          description: "You don't have permission for this action. Contact your property administrator if you believe this is an error.",
          variant: 'destructive',
        })
        return
      }
      const message = err instanceof Error ? err.message : 'Unknown error'
      toast({
        title: 'Deactivation failed',
        description: message,
        variant: 'destructive',
      })
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-lg gap-0 overflow-y-auto bg-background p-6 text-foreground sm:rounded-lg">
        {staff ? (
          <>
            <DialogHeader className="space-y-3 pb-4 text-left">
              <div className="flex items-start gap-3 pr-8">
                <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-destructive/15 text-destructive dark:bg-red-950/70 dark:text-red-300">
                  <AlertTriangle className="h-5 w-5" aria-hidden />
                </div>
                <div className="min-w-0 space-y-2">
                  <DialogTitle className="text-lg font-semibold leading-tight text-foreground">
                    Deactivate Staff Member
                  </DialogTitle>
                  <DialogDescription className="text-sm leading-relaxed text-muted-foreground">
                    You are about to deactivate{' '}
                    <span className="font-semibold text-foreground">{staff.name}</span>.
                  </DialogDescription>
                </div>
              </div>
            </DialogHeader>

            <div className="rounded-lg border border-red-200/90 bg-red-50 px-4 py-3 text-sm shadow-sm dark:border-red-900/70 dark:bg-red-950/45">
              <p className="font-semibold text-foreground">This action will:</p>
              <ul className="mt-2 list-disc space-y-1.5 pl-5 text-muted-foreground marker:text-muted-foreground">
                <li>
                  Remove all access to this property{' '}
                  <span className="font-semibold text-foreground">immediately</span>
                </li>
                <li>
                  Invalidate any active sessions{' '}
                  <span className="font-semibold text-foreground">immediately</span>
                </li>
                <li className="text-muted-foreground">
                  The staff member will be logged out on their next request
                </li>
              </ul>
            </div>

            <DialogFooter className="mt-8 flex w-full flex-row justify-end gap-2 border-t border-border pt-6 sm:gap-2">
              <Button
                type="button"
                variant="outline"
                className="rounded-lg border-border bg-background text-foreground hover:bg-muted"
                onClick={() => onOpenChange(false)}
              >
                Cancel
              </Button>
              <Button
                type="button"
                variant="destructive"
                className="rounded-lg px-4 font-semibold"
                onClick={() => void handleConfirm()}
                disabled={isSubmitting}
              >
                {isSubmitting ? 'Deactivating…' : 'Confirm Deactivation'}
              </Button>
            </DialogFooter>
          </>
        ) : null}
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { useCallback, useEffect, useState } from 'react'
import { useParams, useRouter } from 'next/navigation'
import StaffManagementPageHeader from '@/components/dashboard/staff-management/staff-management-page-header'
import {
  StaffManagementCategoriesDialog,
  type CategoryRow,
  type RoleId,
} from '@/components/dashboard/staff-management/staff-management-dialog/staff-management-categories-dialog'
import { useToast } from '@/hooks/use-toast'
import InviteStaffDialog from '@/components/dashboard/staff-management/staff-management-dialog/invite-staff-dialog'
import { StaffAccessDialog } from '@/components/dashboard/staff-management/staff-management-dialog/staff-access-dialog'
import {
  EditStaffDialog,
  type EditStaffDialogStaff,
} from '@/components/dashboard/staff-management/staff-management-dialog/edit-staff-dialog'
import {
  DeactivateStaffDialog,
  type DeactivateStaffDialogTarget,
} from '@/components/dashboard/staff-management/staff-management-dialog/deactivate-staff-dialog'
import { StaffManagementTable } from '@/components/dashboard/staff-management/staff-management-table'
import StaffManagementFilter, {
  type StaffManagementFilterValue,
} from '@/components/dashboard/staff-management/staff-management-filter'

type StaffManagementStaffPageClientProps = {
  propertyName: string
}

const FILTER_DEBOUNCE_MS = 300

export default function StaffManagementStaffPageClient({
  propertyName,
}: StaffManagementStaffPageClientProps) {
  const params = useParams<{ propertyId: string }>()
  const propertyId =
    typeof params.propertyId === 'string'
      ? params.propertyId
      : Array.isArray(params.propertyId)
        ? (params.propertyId[0] ?? '')
        : ''
  const router = useRouter()
  const { toast } = useToast()
  const [categoriesOpen, setCategoriesOpen] = useState(false)
  const [staffAccessOpen, setStaffAccessOpen] = useState(false)
  const [inviteStaffOpen, setInviteStaffOpen] = useState(false)
  const [editStaffOpen, setEditStaffOpen] = useState(false)
  const [editStaffTarget, setEditStaffTarget] = useState<EditStaffDialogStaff | null>(null)
  const [deactivateStaffOpen, setDeactivateStaffOpen] = useState(false)
  const [deactivateStaffTarget, setDeactivateStaffTarget] =
    useState<DeactivateStaffDialogTarget | null>(null)
  const [isSavingCategories, setIsSavingCategories] = useState(false)
  const [staffTableReloadKey, setStaffTableReloadKey] = useState(0)
  const [filterValue, setFilterValue] = useState<StaffManagementFilterValue>({
    search: '',
    role: 'all',
    category: 'all',
    status: 'all',
  })
  const [debouncedFilterValue, setDebouncedFilterValue] =
    useState<StaffManagementFilterValue>(filterValue)
  const [filterOptions, setFilterOptions] = useState<{
    roles: string[]
    categories: string[]
    statuses: string[]
  }>({
    roles: [],
    categories: [],
    statuses: [],
  })

  useEffect(() => {
    const timeoutId = window.setTimeout(() => {
      setDebouncedFilterValue(filterValue)
    }, FILTER_DEBOUNCE_MS)

    return () => {
      window.clearTimeout(timeoutId)
    }
  }, [filterValue])

  const handleReactivateStaff = useCallback(
    async (target: { id: string; name: string }) => {
      try {
        const res = await fetch(
          `/api/v1/properties/${propertyId}/staff-management/staff/${target.id}`,
          {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ status: 'active' }),
          },
        )
        const json: { success?: boolean; error?: { message?: string } } = await res.json().catch(() => ({}))
        if (!res.ok || json.success !== true) {
          throw new Error(json.error?.message ?? 'Failed to reactivate staff member')
        }
        toast({ title: 'Staff member reactivated', description: `${target.name} can access this property again.` })
        setStaffTableReloadKey((k) => k + 1)
        router.refresh()
      } catch (err: unknown) {
        const message = err instanceof Error ? err.message : 'Unknown error'
        toast({
          title: 'Reactivation failed',
          description: message,
          variant: 'destructive',
        })
      }
    },
    [propertyId, router, toast],
  )

  const handleSaveCategories = async (categoriesByRole: Record<RoleId, CategoryRow[]>) => {
    if (isSavingCategories) return

    try {
      setIsSavingCategories(true)
      const res = await fetch(
        `/api/v1/properties/${propertyId}/staff-management/categories`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            categoriesByRole: {
              admin: categoriesByRole.admin.map((c) => ({ name: c.name })),
              manager: categoriesByRole.manager.map((c) => ({ name: c.name })),
              staff: categoriesByRole.staff.map((c) => ({ name: c.name })),
            },
          }),
        },
      )

      const json: any = await res.json().catch(() => null)
      if (!res.ok || json?.success !== true) {
        console.error('[StaffManagement] Save categories failed', {
          url: `/api/v1/properties/${propertyId}/staff-management/categories`,
          status: res.status,
          statusText: res.statusText,
          response: json,
        })
        throw new Error(json?.error?.message ?? 'Failed to save categories')
      }

      toast({ title: 'Categories saved' })
      router.refresh()
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : 'Unknown error'
      toast({
        title: 'Failed to save categories',
        description: message,
        variant: 'destructive',
      })
    } finally {
      setIsSavingCategories(false)
    }
  }

  return (
    <>
      <div className="space-y-4 sm:space-y-6 px-6 pb-8">
        <StaffManagementPageHeader
          propertyName={propertyName}
          onAccessClick={() => setStaffAccessOpen(true)}
          onCategoriesClick={() => setCategoriesOpen(true)}
          onInviteStaffClick={() => setInviteStaffOpen(true)}
        />

        <StaffManagementFilter
          value={filterValue}
          onChange={setFilterValue}
          roleOptions={filterOptions.roles}
          categoryOptions={filterOptions.categories}
          statusOptions={filterOptions.statuses}
        />

        <StaffManagementTable
          propertyId={propertyId}
          reloadKey={staffTableReloadKey}
          search={debouncedFilterValue.search}
          role={debouncedFilterValue.role}
          category={debouncedFilterValue.category}
          status={debouncedFilterValue.status}
          onFilterOptionsChange={setFilterOptions}
          onEditStaff={(staffMember: EditStaffDialogStaff) => {
            setEditStaffTarget(staffMember)
            setEditStaffOpen(true)
          }}
          onDeactivateStaff={(target: DeactivateStaffDialogTarget) => {
            setDeactivateStaffTarget(target)
            setDeactivateStaffOpen(true)
          }}
          onReactivateStaff={handleReactivateStaff}
        />
      </div>

      <StaffAccessDialog
        open={staffAccessOpen}
        onOpenChange={setStaffAccessOpen}
        propertyId={propertyId}
      />

      <StaffManagementCategoriesDialog
        open={categoriesOpen}
        onOpenChange={setCategoriesOpen}
        onSave={handleSaveCategories}
        propertyId={propertyId}
      />

      <InviteStaffDialog
        open={inviteStaffOpen}
        onOpenChange={setInviteStaffOpen}
        propertyId={propertyId}
        onInviteSent={() => setStaffTableReloadKey((k) => k + 1)}
      />

      <EditStaffDialog
        open={editStaffOpen}
        onOpenChange={(next) => {
          setEditStaffOpen(next)
          if (!next) setEditStaffTarget(null)
        }}
        propertyId={propertyId}
        propertyName={propertyName}
        staff={editStaffTarget}
        onSaved={() => setStaffTableReloadKey((k) => k + 1)}
      />

      <DeactivateStaffDialog
        open={deactivateStaffOpen}
        onOpenChange={(next) => {
          setDeactivateStaffOpen(next)
          if (!next) setDeactivateStaffTarget(null)
        }}
        propertyId={propertyId}
        staff={deactivateStaffTarget}
        onDeactivated={() => setStaffTableReloadKey((k) => k + 1)}
      />
    </>
  )
}

/**
 * Server-side page guard functions for dashboard pages.
 *
 * These replace the individual guard files (operations-modules-page-access.ts,
 * property-settings-page-access.ts, staff-management-page-access.ts) with
 * RBAC-backed implementations.
 */

import type { SupabaseClient } from '@supabase/supabase-js'
import type { ResolvedAccess } from '@/lib/rbac/resolve-access'
import { resolveUserPropertyAccess } from '@/lib/rbac/resolve-access'
import { isManagerOrAbove, isAdminOrAbove } from '@/lib/rbac/roles'
import { hasPermission } from '@/lib/rbac/permissions'
import { staffHasPermission } from '@/lib/rbac/staff-categories'

/**
 * Resolve access for a dashboard page. Returns null if no access.
 *
 * This replaces the multiple separate queries in the old guard functions
 * with a single `resolveUserPropertyAccess()` call.
 */
export async function resolveDashboardAccess(
  supabase: SupabaseClient,
  propertyId: string,
  userId: string,
): Promise<ResolvedAccess | null> {
  return resolveUserPropertyAccess(supabase, propertyId, userId)
}

/**
 * Check if a user can access operations dashboard modules (reservations, sites, guests, etc.).
 *
 * Owner and manager+ only.
 */
export function canAccessOperationsModules(access: ResolvedAccess): boolean {
  if (!access.role) return false
  if (access.isOwner) return true
  if (isManagerOrAbove(access.role)) return true
  return false
}

/**
 * Check if a user can access property settings page.
 *
 * Admin+ only. Manager and staff cannot access settings.
 */
export function canAccessPropertySettings(access: ResolvedAccess): boolean {
  if (!access.role) return false
  return isAdminOrAbove(access.role)
}

export function canViewStaffRoster(access: ResolvedAccess): boolean {
  if (!access.role) return false
  return isManagerOrAbove(access.role)
}

/**
 * Housekeeping dashboard: owner/admin/manager, or staff with housekeeping category.
 */
export function canAccessHousekeepingModule(access: ResolvedAccess): boolean {
  if (!access.role) return false
  if (isManagerOrAbove(access.role)) return true
  return staffHasPermission(access.categories, 'housekeeping.view_assigned')
}

/**
 * Maintenance dashboard: owner/admin/manager, or staff with maintenance category.
 */
export function canAccessMaintenanceModule(access: ResolvedAccess): boolean {
  if (!access.role) return false
  if (isManagerOrAbove(access.role)) return true
  return staffHasPermission(access.categories, 'maintenance.view_assigned')
}

/**
 * Check if a user can manage the staff roster (invite, change roles, deactivate).
 *
 * Admin+ only.
 */
export function canManageStaffRoster(access: ResolvedAccess): boolean {
  if (!access.role) return false
  return isAdminOrAbove(access.role)
}

/**
 * Check if a user can view financial data (transactions, balances, reports).
 *
 * Admin+ always. Manager+ by role permission.
 */
export function canViewFinancials(access: ResolvedAccess): boolean {
